	'messages:apihelp-validatepassword-summary' => 'en:Validate a password against the wiki\'s password policies.',
	'messages:apihelp-validatepassword-extended-description' => 'en:Validity is reported as <samp>Good</samp> if the password is acceptable, <samp>Change</samp> if the password may be used for login but must be changed, or <samp>Invalid</samp> if the password is not usable.',
	'messages:apihelp-validatepassword-param-password' => 'en:Password to validate.',
