	'messages:apierror-badtimestamp' => 'en:Invalid value "$2" for timestamp parameter <var>$1</var>.',
	'messages:apierror-badupload' => 'en:File upload parameter <var>$1</var> is not a file upload; be sure to use <code>multipart/form-data</code> for your POST and include a filename in the <code>Content-Disposition</code> header.',
	'messages:apierror-badurl' => 'en:Invalid value "$2" for URL parameter <var>$1</var>.',
